using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ApiMcpServer.Tools;

/// <summary>
/// MCP tools that wrap a REST API using HttpClient.
/// The SDK injects HttpClient via constructor injection because this is a non-static class.
/// </summary>
[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    [McpServerTool(ReadOnly = true), Description("Retrieve a single resource by its ID.")]
    public async Task<string> GetResource(
        [Description("The unique identifier of the resource to retrieve")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching resource {Id}", id);
        var response = await httpClient.GetAsync($"/posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool(ReadOnly = true), Description("List resources with optional filtering by user ID.")]
    public async Task<string> ListResources(
        [Description("Filter results to this user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        logger.LogInformation("Listing resources from {Url}", url);
        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool(Destructive = false, Idempotent = false), Description("Create a new resource with the given title and body.")]
    public async Task<string> CreateResource(
        [Description("Title for the new resource")] string title,
        [Description("Body content for the new resource")] string body,
        [Description("User ID of the resource author")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating resource for user {UserId}", userId);
        var payload = new { title, body, userId };
        var response = await httpClient.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }
}

